import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.select.Elements;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;

public class DocumentParserTest {

    @Test
    void testExtractMetadata() {
        String html = "<html><head><meta name='author' content='John Doe'><meta name='description' content='Test page'></head><body><h1>Title</h1></body></html>";
        Document doc = Jsoup.parse(html);

        Elements metaTags = doc.select("meta");
        Element authorMeta = metaTags.get(0);
        String author = authorMeta.attr("content");

        assertEquals("John Doe", author);
    }
}
